function usePageMotion() {useEffect(() => {const mm = gsap.matchMedia();mm.add('(prefers-reduced-motion: no-preference)', () => {const ctx = gsap.context(() => {gsap.from('.inner-hero-content > *, .secondary-hero > :not(.secondary-line), .campaign-hero > :not(.campaign-orb), .specialty-hero > div:first-child > *, .rmg-hero > div:first-child > *', { y: 36, opacity: 0, duration: .85, stagger: .13, ease: 'power3.out' });gsap.from('.art-core', { scale: .78, opacity: 0, duration: 1.1, delay: .35, ease: 'back.out(1.7)' });gsap.from('.inner-orbit', { scale: .6, opacity: 0, stagger: .12, duration: 1.2, ease: 'power2.out' });gsap.from('.campaign-orb', { scale: .72, opacity: 0, duration: 1.2, delay: .2, ease: 'power2.out' });['.split-section', '.methodology', '.proof-note', '.directory', '.campaign-body', '.campaign-form', '.secondary-cards', '.contact-layout', '.inner-cta', '.specialty-capabilities', '.rmg-matrix', '.rmg-operating-model', '.rmg-delivery', '.narrative-intro'].forEach((selector) => {document.querySelectorAll(selector).forEach((el) => {gsap.from(el.children, { y: 30, opacity: 0, duration: .8, stagger: .1, ease: 'power2.out', scrollTrigger: { trigger: el, start: 'top 83%', once: true } });});});document.querySelectorAll('.inner-steps article,.secondary-grid article,.campaign-list article,.directory-row,.narrative-article>section,.process-timeline article').forEach((el, i) => {gsap.from(el, { y: 24, opacity: 0, duration: .7, delay: i % 4 * .08, ease: 'power2.out', scrollTrigger: { trigger: el, start: 'top 90%', once: true } });});}, document.body);return () => ctx.revert();});return () => mm.revert();}, []);}
