function ServicePage({ data: p }) {const lang = useLanguage(),bn = serviceBn[p.number];const q = { ...translateDeep(p, lang), ...(lang === 'bn' ? bn : priorityPages[lang]?.[path] || {}) };useTitle(p.label + ' | Deshik Consulting');return <Shell><SplitHero label={'DESHIK / ' + q.label} title={q.title} emphasis={q.emphasis} intro={q.intro} theme={q.theme} cta={q.cta} icon={q.icon} /><div className="inner-marquee"><span>{q.context}</span><span>{draftT("FROM SIGNAL TO STRATEGY")}</span><span>{draftT("DESHIK CONSULTING ↗")}</span></div><section className="inner-section split-section"><div><span className="eyebrow dark">{draftT("01 / THE OPPORTUNITY")}</span><h2>{q.challengeTitle}</h2></div><p>{q.challenge}</p></section><section className="inner-section methodology"><span className="eyebrow dark">{draftT("02 / HOW WE CAN HELP")}</span><div className="section-heading-row"><h2>{draftT("From insight")}<br /><em>to action.</em></h2><p>{q.statement}</p></div><Steps items={translateDeep(q.offer, lang)} /></section><section className="inner-section service-practical"><span className="eyebrow dark">{lang === 'bn' ? '০৩ / ব্যবহারিক ফলাফল' : draftT('03 / PRACTICAL OUTCOMES')}</span><div className="service-practical-grid"><div><h2>{lang === 'bn' ? 'কার জন্য।' : draftT('Who it helps.')}</h2><ul>{(lang === 'bn' && serviceDetailsBn[p.number]?.audience || translateDeep(serviceDetails[p.number].audience, lang)).map((x) => <li key={x}><Check size={17} />{x}</li>)}</ul></div><div><h2>{lang === 'bn' ? 'কী পাবেন।' : draftT('What you take away.')}</h2><ul>{(lang === 'bn' && serviceDetailsBn[p.number]?.outputs || translateDeep(serviceDetails[p.number].outputs, lang)).map((x) => <li key={x}><Check size={17} />{x}</li>)}</ul></div></div>{serviceDetails[p.number].questions.length > 0 && <div className="service-faq"><h3>{lang === 'bn' ? 'প্রায়শই জিজ্ঞাসা' : draftT('Common questions')}</h3>{translateDeep(serviceDetails[p.number].questions, lang).map(([question, answer]) => <details key={question}><summary>{question}</summary><p>{answer}</p></details>)}</div>}</section>{p.number === '01' && <section className="rmg-teaser"><div><span className="eyebrow dark">{draftT("BANGLADESH RMG / FEATURED FOCUS")}</span><h2>{draftT("From the sewing floor to the product record.")}</h2><p>{draftT("Explore a deeper, Bangladesh-focused DPP information journey for apparel exporters, suppliers and the teams that connect them.")}</p><a href="/services/digital-product-passport/rmg-bangladesh/">{draftT("Explore the RMG & DPP guide") + " "}<ArrowUpRight size={18} /></a><a className="rmg-teaser-second" href="/insights/dpp-readiness-questions/#dpp-wizard">{draftT("Try the DPP readiness wizard") + " "}<ArrowUpRight size={18} /></a><a className="rmg-teaser-second" href="/experience/dpp-product-journey/">{draftT("Explore the fictional product journey") + " "}<ArrowUpRight size={18} /></a></div><ScanLine size={91} strokeWidth={.7} /></section>}{p.number === '02' && <section className='factory-demo-teaser'><div><span className='eyebrow dark'>{draftT('INTERACTIVE / FACTORY OPERATIONS')}</span><h2>{draftT('From a signal to a better decision.')}</h2><p>{draftT('Try a fictional operations studio: compare sample stop, quality and energy questions, then shape a bounded pilot conversation. No live equipment or measured result is shown.')}</p><a href='/experience/factory-operations-studio/'>{draftT('Explore the fictional factory studio')} <ArrowUpRight size={18}/></a></div><Factory size={85} strokeWidth={.8}/></section>}<section className="inner-section proof-note"><div><span className="eyebrow dark">{draftT("IMPORTANT CONTEXT")}</span><p>{q.note}</p></div><a href={p.related}>{q.relatedText}<ArrowUpRight size={19} /></a></section><CTA title="Ready to find your next move?" sub="Tell us the challenge you're working through. We'll start with a conversation." /></Shell>;}
function CTA({ title, sub }) {return <section className="inner-cta"><span className="eyebrow">{draftT("THE NEXT CONVERSATION")}</span><h2>{title}</h2><p>{sub}</p><a href="/contact/">{draftT("Let's talk") + " "}<ArrowUpRight size={20} /></a></section>;}
function Overview() {const lang = useLanguage();useTitle('Services | Deshik Consulting');return <Shell><SplitHero label={draftT('WHAT WE DO / THE OVERVIEW')} title={draftT("Expertise for what's next.")} emphasis={draftT("what's next")} intro={draftT('Focused thinking, connected capabilities and practical perspectives for the challenges ahead.')} cta={draftT('Start a conversation')} icon={Layers3} /><DeferredJourney compact /><section className="inner-section directory"><span className="eyebrow dark">{draftT("01 / OUR CAPABILITIES")}</span><h2>{draftT("Find your way") + " "}<em>forward.</em></h2>{translateDeep(serviceItems, lang).map(([n, u, d], i) => <a href={u} className="directory-row" key={u}><span>0{i + 1}</span><strong>{n}</strong><small>{d}</small><ArrowUpRight size={21} /></a>)}</section><NextMoveSection /><TopicDirectory sections={topicSections['/services/']} /><CTA title="Not sure where to start?" sub="Tell us what you're trying to achieve and we'll explore the right next step together." /></Shell>;}
const campaigns = { '/dpp-readiness/': { label: 'DPP READINESS / DISCOVERY', title: 'Get ahead of the product-data question.', emphasis: 'product-data', intro: 'A focused conversation to explore your products, markets, information sources and possible next steps.', items: [['01', 'Your products', 'What products and markets matter to your business?'], ['02', 'Your data', 'Where does product and supplier information live today?'], ['03', 'Your next step', 'What could a realistic readiness pilot look like?']], link: '/services/digital-product-passport/', linkText: 'Explore the full DPP service' }, '/automation-assessment/': { label: 'INDUSTRIAL AUTOMATION / DISCOVERY', title: 'Find the right opportunity to automate.', emphasis: 'automate', intro: 'Start with the operational challenges you want to solve—not a predetermined technology.', items: [['01', 'Your operation', 'Which processes are constrained by downtime, quality or visibility?'], ['02', 'Your systems', 'What equipment, people and data are already in place?'], ['03', 'Your next step', 'Which limited use case could be evaluated first?']], link: '/services/industrial-automation/', linkText: 'Explore the full automation service' } };
function Campaign({ data: p }) {const lang = useLanguage(),q = { ...translateDeep(p, lang), ...(lang === 'bn' ? campaignBn[path] : priorityPages[lang]?.[path] || {}) };useTitle(p.label + ' | Deshik Consulting');return <Shell compact><section className="campaign-hero"><span className="eyebrow">{q.label}</span><h1>{q.title}</h1><p>{q.intro}</p><a href="#enquire" className="button-primary">{draftT("Start the conversation") + " "}<ArrowUpRight size={18} /></a><div className="campaign-orb"><ScanLine size={80} strokeWidth={.8} /></div></section><section className="inner-section campaign-body"><div><span className="eyebrow dark">{draftT("WHAT WE'LL EXPLORE")}</span><h2>{draftT("A clearer view")}<br /><em>of what comes next.</em></h2><a href={p.link}>{q.linkText} <ArrowUpRight size={17} /></a></div><div className="campaign-list">{q.items.map(([n, t, d]) => <article key={n}><span>{n}</span><h3>{t}</h3><p>{d}</p></article>)}</div></section><ReadinessExplorer type={path === '/dpp-readiness/' ? 'dpp' : 'automation'} /><section className="inner-section campaign-form" id="enquire"><div><span className="eyebrow dark">{draftT("GET IN TOUCH")}</span><h2>{draftT("Let's begin")}<br /><em>with a conversation.</em></h2><p>{draftT("This preview opens your email application. A secure website form and CRM routing will be added with the Laravel backend.")}</p></div><LeadForm topic={q.label} /></section></Shell>;}
function LeadForm({ topic = 'General enquiry' }) {
  const [values, setValues] = useState({ name: '', email: '', company: '', message: '' });
  const [attempted, setAttempted] = useState(false), [copyStatus, setCopyStatus] = useState('');
  const emailText = `To: contact@deshikconsulting.com\nSubject: ${topic} — ${values.company}\n\nName: ${values.name}\nEmail: ${values.email}\nCompany: ${values.company}\n\nProject:\n${values.message}`;
  const submit = (e) => {
    e.preventDefault(); setAttempted(true); setCopyStatus('');
    const subject = encodeURIComponent(topic + ' — ' + values.company);
    const body = encodeURIComponent(`Name: ${values.name}\nEmail: ${values.email}\nCompany: ${values.company}\n\nProject:\n${values.message}`);
    window.location.href = 'mailto:contact@deshikconsulting.com?subject=' + subject + '&body=' + body;
  };
  async function copy() {
    try { await navigator.clipboard.writeText(emailText);setCopyStatus(draftT('Copied. Paste the message into your email application and send it yourself.')); }
    catch { setCopyStatus(draftT('Automatic copying is unavailable. Select and copy the message below.')); }
  }
  return <form onSubmit={submit} className="lead-form"><label>{draftT("Your name")}<input required autoComplete="name" value={values.name} onChange={(e) => setValues({ ...values, name: e.target.value })} placeholder={draftT("Your name")} /></label><label>{draftT("Work email")}<input required type="email" autoComplete="email" value={values.email} onChange={(e) => setValues({ ...values, email: e.target.value })} placeholder="you@company.com" /></label><label>{draftT("Company")}<input required autoComplete="organization" value={values.company} onChange={(e) => setValues({ ...values, company: e.target.value })} placeholder={draftT("Your organization")} /></label><label>{draftT("What are you working on?")}<textarea required rows="4" value={values.message} onChange={(e) => setValues({ ...values, message: e.target.value })} placeholder={draftT("A few words about your project")} /></label><button className="dark-button" type="submit">{draftT("Open email draft") + " "}<ArrowUpRight size={18} /></button><small>{draftT("No information is submitted to this preview site. Your email app must open and you must send the message yourself.")}</small>{attempted && <div className="email-fallback"><strong>{draftT('Did an email draft open?')}</strong><p>{draftT('Nothing has been sent by this website. If your email application did not open, copy the prepared message and email it yourself.')}</p><button type="button" onClick={copy}>{draftT('Copy prepared email')}</button><label>{draftT('Prepared email (select to copy)')}<textarea readOnly rows="8" value={emailText} onFocus={(e) => e.target.select()} /></label><span role="status">{copyStatus}</span></div>}</form>;
}
const secondary = {
  '/industries/': { tag: 'WHERE WE WORK', title: 'Different industries. Shared ambition.', intro: 'We work across business contexts where transformation requires both a clear direction and practical execution.', cards: [['Manufacturing', 'Connect shop-floor visibility, equipment data and operational improvement priorities.'], ['Export supply chains', 'Bring together product attributes, supplier inputs and traceability workflows for export readiness.'], ['Technology businesses', 'Translate product, technology and market questions into executable growth plans.']], note: 'Sector-specific experience and client examples will be published only after verification.' },
  '/work/': { tag: 'OUR WORK', title: 'Progress is built together.', intro: 'Our work begins with a defined problem, clear responsibilities and outcomes that can be evidenced—not unverified headline numbers.', cards: [['Explore the challenge', 'We begin with context, constraints and the people closest to the work.'], ['Shape the response', 'We connect expertise, priorities and a deliverable plan.'], ['Make it measurable', 'We define what can be demonstrated and documented.']], note: 'Named case studies are being prepared. We will publish client names and outcomes only with permission and supporting evidence.' },
  '/insights/': { tag: 'PERSPECTIVES', title: 'Questions worth exploring.', intro: 'Fresh thinking on product intelligence, industrial systems and the decisions shaping tomorrow.', cards: [['Digital Product Passports', 'What manufacturers should ask before choosing a technology solution.'], ['Industrial Automation', 'Why a strong automation pilot starts with the operational question.'], ['Strategy & Execution', 'How to turn a complex ambition into practical next steps.']], note: 'Guides are draft editorial content and require subject-matter and regulatory review before public launch.' },
  '/about/': { tag: 'ABOUT DESHIK', title: 'Ideas into action. Together.', intro: 'Deshik Consulting brings a practical, collaborative perspective to business transformation, connecting global ideas with local realities.', cards: [['Our perspective', 'Understand the local market and the operational reality before recommending a path forward.'], ['Our approach', 'Work alongside teams to turn research, decisions and priorities into an achievable delivery plan.'], ['Our home', 'Based in Dhaka, Bangladesh, with an outlook beyond borders.']], note: 'Leadership biographies, client names, office information and company history are pending verification and publication approval.' }
};
const articleData = { ...newArticles,
  '/insights/dpp-readiness-questions/': { tag: 'PRODUCT INTELLIGENCE / GUIDE', title: 'Five questions to ask before starting a DPP project', intro: 'A practical starting point for teams exploring product-data readiness.', sections: [['01 / Which products and markets matter?', 'List the product categories you sell and the markets in which they are placed. A DPP obligation is not universal: applicability and timing depend on the relevant legal instrument and product-specific measures.'], ['02 / Where does the information live?', 'Identify what is held in ERP, PLM, supplier files, spreadsheets and quality records. Document who owns each field and how often it changes.'], ['03 / What can suppliers provide?', 'Ask suppliers about material information, traceability and evidence. Note missing fields and the effort needed to collect them reliably.'], ['04 / Which systems must connect?', 'Map identifiers, existing data flows and access needs before choosing a new platform. A pilot should test data quality as much as the user interface.'], ['05 / What will the first pilot prove?', 'Choose a limited product group, define ownership and agree what a successful pilot must demonstrate. Review requirements with a qualified specialist before making compliance claims.']], note: 'The EU Ecodesign for Sustainable Products Regulation establishes a framework for product-specific requirements. Separately, Article 77 of the EU Batteries Regulation specifies a battery passport from 18 February 2027 for certain battery categories. This article is general information, not legal advice.', source: 'https://eur-lex.europa.eu/eli/reg/2024/1781/oj', second: 'https://eur-lex.europa.eu/eli/reg/2023/1542/oj', related: '/services/digital-product-passport/', cta: 'Explore DPP consulting' },
  '/insights/automation-pilot/': { tag: 'CONNECTED OPERATIONS / GUIDE', title: 'How to choose an industrial automation pilot', intro: 'Start with a measurable operational question, not a shopping list of technologies.', sections: [['01 / Define the operating problem', 'Write down the problem in terms that the production team recognizes: recurring stops, delayed quality feedback, manual data entry or limited visibility.'], ['02 / Establish a baseline', 'Agree how the current process is measured. Without a baseline, it is difficult to distinguish a promising pilot from a persuasive demo.'], ['03 / Review constraints', 'Check equipment interfaces, access permissions, operator workflows, machine safety, downtime windows and OT security before selecting an integration approach.'], ['04 / Keep the scope small', 'Pick a line, process or reporting workflow with clear owners and a limited technical boundary. Confirm what must be tested before broader deployment.'], ['05 / Decide what happens next', 'Document training, maintenance, handover and measurable success criteria so a pilot can support a genuine scale-or-stop decision.']], note: 'Examples are planning guidance, not claims about completed Deshik projects. Site access, controls work and installation require agreed scope and suitably qualified personnel.', related: '/services/industrial-automation/', cta: 'Explore Industrial Automation' } };
function Article({ data: original }) {const lang = useLanguage(),p = translateDeep(original, lang);useTitle(p.title + ' | Deshik Consulting');return <Shell><section className="secondary-hero article-hero"><span className="eyebrow">{draftT("DESHIK /") + " "}{p.tag}</span><h1>{p.title}</h1><p>{p.intro}</p><div className="secondary-line"><span>{lang === 'bn' ? 'বিশেষজ্ঞ পর্যালোচনা সাপেক্ষে' : draftT('EDITORIAL GUIDE / REVIEW REQUIRED')}</span><span>{draftT("DESHIK CONSULTING")}</span></div></section>{original === articleData['/insights/dpp-readiness-questions/'] && <React.Suspense fallback={<div className="dpp-feature-loading">{draftT("Preparing interactive guide…")}</div>}><DppGuideExperience /></React.Suspense>}<section className="inner-section article-layout"><div><span className="eyebrow dark">{draftT("IN THIS ARTICLE")}</span>{p.sections.map(([h], i) => <a href={'#article-' + i} key={h}>{h} <ArrowUpRight size={14} /></a>)}<a className="article-back" href="/insights/">{draftT("← All insights")}</a></div><article>{p.sections.map(([h, body], i) => <section id={'article-' + i} key={h}><h2>{h}</h2><p>{body}</p></section>)}<aside>{p.note}{p.source && <div className="article-sources">{draftT("Official texts:") + " "}<a href={p.source} target="_blank" rel="noopener noreferrer">{draftT("ESPR ↗")}</a>{p.second && <> · <a href={p.second} target="_blank" rel="noopener noreferrer">{draftT("EU Batteries Regulation ↗")}</a></>}</div>}</aside><a className="dark-button" href={p.related}>{p.cta} <ArrowUpRight size={18} /></a>{original === articleData['/insights/dpp-readiness-questions/'] && <a className="article-tool-link" href="/resources/dpp-data-map/">{draftT('Open the product-data worksheet')} <ArrowUpRight size={17}/></a>}{original === articleData['/insights/dpp-readiness-questions/'] && <a className="article-tool-link" href="/experience/dpp-product-journey/">{draftT('Explore the fictional product record')} <ArrowUpRight size={17}/></a>}{original === articleData['/insights/automation-pilot/'] && <a className="article-tool-link" href="/resources/automation-pilot-canvas/">{draftT('Open the automation pilot canvas')} <ArrowUpRight size={17}/></a>}{original === articleData['/insights/automation-pilot/'] && <a className="article-tool-link" href="/experience/factory-operations-studio/">{draftT('Explore the fictional factory studio')} <ArrowUpRight size={17}/></a>}</article></section></Shell>;}
function TopicDirectory({ sections: original }) {const lang = useLanguage(),sections = translateDeep(original, lang);return <div className="topic-directory">{sections.map((section) => <section className="topic-section" id={section.id} key={section.id}><div><span className="eyebrow dark">{draftT("DESHIK /") + " "}{section.id.replaceAll('-', ' ').toUpperCase()}</span><h2>{section.title}</h2><p>{section.intro}</p></div><div><ul>{section.topics.map((t) => <li key={t}>{t}</li>)}</ul><p className="topic-note">{section.note}</p></div></section>)}</div>;}
function Secondary({ data: p }) {const lang = useLanguage(),q = { ...translateDeep(p, lang), ...(lang === 'bn' ? secondaryBn[path] : priorityPages[lang]?.[path] || {}) };useTitle(p.tag + ' | Deshik Consulting');return <Shell><section className="secondary-hero"><span className="eyebrow">{draftT("DESHIK /") + " "}{q.tag}</span><h1>{q.title}</h1><p>{q.intro}</p><div className="secondary-line"><span>{draftT("EXPLORE BELOW ↓")}</span><span>{draftT("DESHIK CONSULTING / 2026")}</span></div></section><section className="inner-section secondary-cards"><span className="eyebrow dark">{draftT("PERSPECTIVES / 01—03")}</span><div className="secondary-grid">{q.cards.map(([n, d], i) => path === '/insights/' ? <a className="secondary-card-link" href={i === 0 ? '/insights/dpp-readiness-questions/' : i === 1 ? '/insights/automation-pilot/' : '/services/strategy-growth/'} key={n}><span>0{i + 1}</span><h2>{n}</h2><p>{d}</p><ArrowUpRight size={22} /></a> : <article key={n}><span>0{i + 1}</span><h2>{n}</h2><p>{d}</p><ArrowUpRight size={22} /></article>)}</div><p className="editorial-note">{q.note}</p></section>{path === '/insights/' && <EditorialLibrary />}{path === '/insights/' && <section className='story-directory'><div><span className='eyebrow dark'>{draftT("STORYTELLING / ILLUSTRATIVE FIELD NOTES")}</span><h2>{draftT("Stories that make a complex question human.")}</h2><p>{draftT("These narratives are fictional composites—not client case studies.")}</p></div><a href='/insights/rmg-product-story/'><span>{draftT("PRODUCT DATA / RMG")}</span><strong>{draftT("The missing thread in a garment’s product story")}</strong><ArrowUpRight size={20} /></a><a href='/insights/factory-signal-story/'><span>{draftT("OPERATIONS / AUTOMATION")}</span><strong>{draftT("A factory signal is not yet a decision")}</strong><ArrowUpRight size={20} /></a></section>}{path === '/industries/' ? <><IndustryExtras /><IndustryPlaybookGrid /></> : path === '/about/' ? <><BrandManifesto compact /><AboutLandingDirectory /><AboutExtras /></> : path === '/work/' ? <WorkExtras /> : null}{path === '/work/' ? <section className='work-process-links'><div><span className='eyebrow dark'>{draftT("TWO SIDES OF OUR APPROACH")}</span><h2>{draftT("How we think. How we deliver.")}</h2></div><a href='/approach/consulting-process/'>{draftT("Our Consulting Process") + " "}<ArrowUpRight size={19} /></a><a href='/approach/service-delivery/'>{draftT("Our Service Delivery Process") + " "}<ArrowUpRight size={19} /></a></section> : null}{path === '/work/' ? <ProofPreview /> : null}<TopicDirectory sections={topicSections[path] || []} /><CTA title="Let's talk about what's next." sub="A useful conversation starts with what matters most to your organization." /></Shell>;}
function Contact() {const lang = useLanguage();const topicKey = new URLSearchParams(window.location.search).get('topic');const topicNames = { tdg: 'Trusted Data Gateway (TDG)', dpp: 'Digital Product Passport', rmg: 'RMG product-data readiness', automation: 'Industrial Automation', strategy: 'Strategy & Growth', digital: 'Digital Transformation', ai: 'Data & Artificial Intelligence' };const selectedTopic = Object.hasOwn(topicNames, topicKey) ? topicNames[topicKey] : null;useTitle('Contact | Deshik Consulting');return <Shell><section className="secondary-hero"><span className="eyebrow">{draftT("GET IN TOUCH / DESHIK")}</span><h1>{draftT("Let’s start with a conversation.")}</h1><p>{draftT("Tell us a little about your challenge, your organization and where you'd like to go next.")}</p></section><section className="inner-section contact-layout"><div><span className="eyebrow dark">{draftT("CONNECT WITH US")}</span><h2>{draftT("Good work begins")}<br /><em>with a question.</em></h2><div className="contact-details"><a href="mailto:contact@deshikconsulting.com"><Mail size={19} /> contact@deshikconsulting.com</a><span><MapPin size={19} />{" " + draftT("Uttara, Dhaka, Bangladesh")}</span><small>{draftT("Contact details and meeting locations are subject to final confirmation.")}</small></div></div><div className="contact-form-wrap">{selectedTopic && <div className="contact-context"><span>{draftT("YOUR CONVERSATION STARTER")}</span><strong>{draftT(selectedTopic)}</strong><a href="/services/#find-your-path">{draftT("Change direction")} ↗</a></div>}<LeadForm topic={selectedTopic || "Website contact enquiry"} /></div></section><section className="contact-options"><div className="expanded-title"><span className="eyebrow dark">{draftT("MAKE YOUR ENQUIRY USEFUL")}</span><h2>{draftT("A little context goes a long way.")}</h2><p>{draftT("Tell us about your organization, the product or process involved, the market you serve and the decision you need to make next. Please do not send confidential operational data through this preview.")}</p></div><div className="contact-paths"><a href="/services/trusted-data-gateway/"><Database size={24} /><strong>{draftT("Trusted Data Gateway")}</strong><span>{draftT("Explore how your existing product-data sources could connect through a governed gateway.")}</span><ArrowUpRight size={18} /></a><a href="/dpp-readiness/"><ScanLine size={24} /><strong>{draftT("Product data & DPP")}</strong><span>{draftT("Explore your product categories, data sources and a first pilot.")}</span><ArrowUpRight size={18} /></a><a href="/automation-assessment/"><Factory size={24} /><strong>{draftT("Industrial Automation")}</strong><span>{draftT("Describe the operational question and systems you already have.")}</span><ArrowUpRight size={18} /></a><a href={whatsappUrl('a consulting project')} target="_blank" rel="noopener noreferrer"><MessageCircle size={24} /><strong>{draftT("WhatsApp enquiry")}</strong><span>{draftT("Start a conversation using the number in Deshik’s supplied company profile.")}</span><ArrowUpRight size={18} /></a></div><p className="editorial-note">{draftT("WhatsApp number and routing require Deshik’s approval before production launch. The contact form in this preview opens an email draft rather than transmitting data to a server.")}</p></section></Shell>;}
