function useTitle(title) {useEffect(() => {document.title = title;}, [title]);}
export default function Pages() {useEffect(() => {if (!window.location.hash) return;const id = decodeURIComponent(window.location.hash.slice(1));let attempts = 0;const timer = setInterval(() => {const target = document.getElementById(id);if (target) {target.scrollIntoView({ behavior: 'instant', block: 'start' });clearInterval(timer);} else if (++attempts > 30) clearInterval(timer);}, 100);return () => clearInterval(timer);}, []);if (pages[path]) return <ServicePage data={pages[path]} />;if (campaigns[path]) return <Campaign data={campaigns[path]} />;if (secondary[path]) return <Secondary data={secondary[path]} />;if (industryPages[path]) return <IndustryDetail data={industryPages[path]} Shell={Shell} CTA={CTA} />;if (playbooks[path]) return <IndustryPlaybook data={playbooks[path]} Shell={Shell} CTA={CTA} />;if (demoStories[path]) return <DemoStory story={demoStories[path]} Shell={Shell} CTA={CTA} />;if (articleData[path]) return <Article data={articleData[path]} />;if (path === '/services/trusted-data-gateway/') return <TdgPage Shell={Shell} />;if (path === '/services/') return <Overview />;if (path === '/contact/') return <Contact />;if (aboutPages[path]) return <AboutDetail data={aboutPages[path]} current={path} Shell={Shell} />;if (path === '/about/consultants/') return <ConsultantDirectory Shell={Shell} />;if (path === '/about/work-as-consultant/') return <ConsultantInterest Shell={Shell} />;if (path === '/about/leadership/') return <LeadershipDirectory Shell={Shell} />;if (people[path]) return <LeaderProfile person={people[path]} Shell={Shell} />;if (path === '/experience/factory-operations-studio/') return <React.Suspense fallback={<div className='journey-page-loading'>{draftT('Preparing the factory studio…')}</div>}><FactoryStudio Shell={Shell} /></React.Suspense>;if (path === '/experience/dpp-product-journey/') return <React.Suspense fallback={<div className='journey-page-loading'>{draftT('Preparing the product journey…')}</div>}><DppJourney Shell={Shell} /></React.Suspense>;if (path === '/resources/') return <ResourceHub Shell={Shell} />;if (path === '/resources/dpp-data-map/') return <DppDataMapper Shell={Shell} />;if (path === '/resources/automation-pilot-canvas/') return <AutomationPilotCanvas Shell={Shell} />;if (specialtyContent[path]) return <SpecialtyPage data={specialtyContent[path]} Shell={Shell} CTA={CTA} />;if (path === '/approach/service-delivery/') return <ProcessPage type='delivery' Shell={Shell} CTA={CTA} />;if (path === '/approach/consulting-process/') return <ProcessPage type='consulting' Shell={Shell} CTA={CTA} />;if (path === '/services/digital-product-passport/rmg-bangladesh/') return <RmgDppPage Shell={Shell} CTA={CTA} />;if (stories[path]) return <StoryArticle data={stories[path]} Shell={Shell} CTA={CTA} />;return <NotFound />;}
